\label{lem-1}
The critical manifold $S_0$ has the following properties.
\begin{enumerate}
\item The sub-manifold $S_0^0$ is normally attracting under the flow of Equation~\eqref{eq-4}.
\item The sub-manifold $S_0^1$ is normally repelling (normally attracting) for $u<\frac{1+a\phi}{2\phi}$ ($u>\frac{1+a\phi}{2\phi}$), losing hyperbolicity at the fold point $F:\ \big(\frac{1+a\phi}{2\phi},\frac{(1-a\phi)^2}{4\phi}\big)$.
\end{enumerate}

\label{prop-1}
The reduced flow of Equation~\eqref{eq-2} can be written as
\begin{subequations}\label{eq-5}
\begin{align}
\dot{v} &=-v \qquad\text{on }S_0^0\text{ and} \label{eq-5a} \\
\dot{u} &=(u-a)\frac{(1-\phi u)(u-1)}{1+a\phi-2\phi u} \qquad\text{on }S_0^1, \label{eq-5b}
\end{align}
\end{subequations}
respectively.

\label{prop-2}
Let $a\in(0,1)$ be fixed, and let $\phi_{\rm min}:=(2-a)^{-1}\in(\frac{1}{2},1)$.
\begin{enumerate}
\item The extinction state $O$ is attracting under the reduced flow on $S_0^0$.
\item The prey-only state $P_1$ is attracting under the reduced flow on $S_0^1$.
\item The prey-only state $P_2$ is repelling under the reduced flow on $S_0^1$.
\item The coexistence state $S$ is repelling under the reduced flow on $S_0^1$ for $\phi\in(0,\phi_{\rm min})$ and attracting for $\phi\in(\phi_{\rm min},\phi_{\rm max})$.
\end{enumerate}

\begin{enumerate}
\item For $\phi=1=a$, the manifold $S_0^1$ degenerates to $v=-(u-1)^2$, with the equilibria $P_i$ ($i=1,2)$ and $S$ merging with the fold point $F$ at $u=1$; that case is excluded by assumption, however.
\item The equilibria $P_i$ ($i=1,2$) are always distinct from $F$, as either can only coincide with $F$ for $\phi=a^{-1}>1$, which is again inadmissible.
\item As in \cite{vanselow_2019_when}, the coexistence state $S$ merges with $F$ and undergoes a (singular) Hopf bifurcation at $\phi=\phi_{\rm min}$; for $\phi=\phi_{\rm max}$, the equilibria $S$ and $P_2$ exchange stability in a transcritical bifurcation.
\end{enumerate}

\label{prop-3}
The reduced flow of Equation~\eqref{eq-8} on $S_{0,\phi}^1$ can be written as
\begin{subequations}\label{eq-9}
\begin{align}
\dot{u} &=(u-a)\frac{(1-\phi u)(u-1)+ru}{1+a\phi-2\phi u}, \label{eq-9a} \\
\dot{\phi} &=r.
\end{align}
\end{subequations}

\label{prop-4}
Let $r,\delta>0$ be sufficiently small, and let $\phi\in(\phi_{{\rm min},\delta},\phi_{{\rm max},\delta})$. Then, Equation~\eqref{eq-ramped system} admits a unique, ecologically relevant folded singularity $FS_{\phi,r}$ which satisfies the following properties.
\begin{enumerate}
\item The singularity 
\begin{align}\label{eq-13}
FS_{\phi,r}:\ \bigg(1-\frac{2-a}{1-a}r+\mathcal{O}(r^2),\,\frac{1}{2-a}+\frac{2}{(1-a)(2-a)}r+\mathcal{O}(r^2)\bigg)
\end{align}
is a regular perturbation of $S_\phi$, with $FS_{\phi,0}:\ (1,\phi_{\rm min})$.
\item The singularity $FS_{\phi,r}$ is a folded saddle equilibrium, with eigenvalues 
\begin{align}\label{eq-11}
\lambda_-=-\frac{(1-a)^2}{2-a}+\mathcal{O}(r)\quad\text{and}\quad \lambda_+=(2-a)r+\mathcal{O}(r^2)
\end{align}
and corresponding eigenvectors 
\begin{align}\label{eq-12}
\mathbf{v}_-=\bigg(1, -\frac{2}{(1-a)^2}r+\mathcal{O}(r^2)\bigg)^T\quad\text{and}\quad \mathbf{v}_+=\bigg(-\frac{(2-a)^2}{(1-a)^2}r+\mathcal{O}(r^2), 1\bigg)^T, 
\end{align}
respectively.    
\end{enumerate}

For sufficiently small $r,\delta>0$, there exists a critical rate
    \begin{align}\label{eq-rcrit}
    r_{\rm crit}=\frac{(1-a)(2-a)}{2}\delta+\mathcal{O}(\delta^2)
    \end{align}
    such that the trajectory $\gamma_I$ of the reduced flow in \eqref{eq-8} with initial condition $I$ behaves as follows.
    \begin{enumerate}
        \item For $r<r_{\rm crit}$, the trajectory $\gamma_I$ remains on $S^{1, a}_{0, \phi}$ for $\phi\in(\phi_{\rm min,\delta},\phi_{\rm max,\delta})$.
        \item For $r=r_{\rm crit}$, $\gamma_I$ lies on the singular canard $\Gamma_0$ and reaches the fold line $F_{\phi}$ at $FS_{\phi,r}$ before crossing onto $S_{0, \phi}^{1, r}$.
        \item For $r>r_{\rm crit}$, $\gamma_I$ reaches the fold curve $F_{\phi}$ in finite time, where it leaves $S_{0, \phi}^1$ along a fast fibre under the layer flow of \eqref{eq-ramped layer}.
    \end{enumerate} 
    \label{prop:critical rate}

For sufficiently small $r,\delta>0$, the critical rate $r_{\rm crit}$ defined in Proposition~\ref{prop:critical rate} admits the expansion
    \begin{equation}
        r_{\rm crit}=\frac{(1-a)(2-a)}{2}\delta+\frac{(1-a)(2-a)^3}{2}\delta^2+\mathcal{O}(\delta^3).
        \label{eq-rcrit-order2}
    \end{equation}
    \label{cor:critical rate}
